
// 兼容旧版六参数景点调用，以及新版八参数三语景点调用。
function makeAttraction(nameZh, nameKo, arg3, arg4, arg5, arg6, arg7, arg8) {
    if (arguments.length >= 8) {
        return {
            name: { zh: nameZh, ko: nameKo, en: arg3 },
            type: arg4,
            time: arg5,
            description: { zh: arg6, ko: arg7, en: arg8 }
        };
    }
    return {
        name: { zh: nameZh, ko: nameKo },
        type: arg3,
        time: arg4,
        description: { zh: arg5, ko: arg6 }
    };
}

// 兼容旧版四参数美食调用，以及新版六参数三语美食调用。
function makeFood(nameZh, nameKo, arg3, arg4, arg5, arg6) {
    if (arguments.length >= 6) {
        return {
            name: { zh: nameZh, ko: nameKo, en: arg3 },
            type: "美食",
            description: { zh: arg4, ko: arg5, en: arg6 }
        };
    }
    return {
        name: { zh: nameZh, ko: nameKo },
        type: "美食",
        description: { zh: arg3, ko: arg4 }
    };
}

function makeCity(attractions, foods, transportZh, transportKo, transportEn = "") {
    return {
        attractions: attractions,
        foods: foods,
        transport: {
            zh: transportZh,
            ko: transportKo,
            en: transportEn
        }
    };
}

