for (const [cityName, cityInfo] of Object.entries(additionalCityData)) {
    travelData[cityName] = {
        attractions: cityInfo.attractions.map(item => ({
            name: { zh: item[0], ko: item[1], en: item[2] },
            type: item[3],
            time: item[4],
            description: { zh: item[5], ko: item[6], en: item[7] }
        })),
        foods: cityInfo.foods.map(item => ({
            name: { zh: item[0], ko: item[1], en: item[2] },
            type: "美食",
            description: { zh: item[3], ko: item[4], en: item[5] }
        })),
        transport: {
            zh: cityInfo.transport[0],
            ko: cityInfo.transport[1],
            en: cityInfo.transport[2]
        }
    };
}

