// 将新增城市写入 travelData。
// 如果某城市已经存在，不覆盖原有数据。
for (const [cityName, cityInfo] of Object.entries({
    ...extraDestinationsPack2026,
    ...koreaNewDestinations2026,
    ...koreaDestinationsPack2026B,
    ...koreaDestinationsPack2026C
})) {
    if (travelData[cityName]) {
        console.warn("地区已存在，跳过新增：" + cityName);
        continue;
    }

    travelData[cityName] = {
        attractions: cityInfo.attractions.map(item => ({
            name: {
                zh: item[0],
                ko: item[1],
                en: item[2]
            },
            type: item[3],
            time: item[4],
            description: {
                zh: item[5],
                ko: item[6],
                en: item[7]
            }
        })),
        foods: cityInfo.foods.map(item => ({
            name: {
                zh: item[0],
                ko: item[1],
                en: item[2]
            },
            description: {
                zh: item[3],
                ko: item[4],
                en: item[5]
            }
        })),
        transport: {
            zh: cityInfo.transport[0],
            ko: cityInfo.transport[1],
            en: cityInfo.transport[2]
        }
    };
}
// ======================================================
// 现有地区内容扩充工具（2026）
// 不新增地区；不覆盖原有景点；支持中韩英三语
// ======================================================

function getTravelText(value, language = "zh") {
    if (typeof value === "string") {
        return value;
    }

    if (value && typeof value === "object") {
        return value[language] || value.zh || value.ko || value.en || "";
    }

    return "";
}


// 将补充景点安全地合并到已有地区
function addAttractionsSafely(cityName, newAttractions) {
    const city = travelData[cityName];

    if (!city) {
        console.warn("找不到地区，跳过补充：" + cityName);
        return;
    }

    if (!Array.isArray(city.attractions)) {
        city.attractions = [];
    }

    for (const item of newAttractions) {
        const newNameZh = getTravelText(item.name, "zh").trim();

        if (!newNameZh) {
            console.warn("景点缺少中文名称，跳过：", item);
            continue;
        }

        const alreadyExists = city.attractions.some(existing => {
            const existingNameZh = getTravelText(existing.name, "zh").trim();
            return existingNameZh === newNameZh;
        });

        if (alreadyExists) {
            console.log("景点已存在，跳过：" + cityName + " - " + newNameZh);
            continue;
        }

        city.attractions.push({
            name: {
                zh: getTravelText(item.name, "zh"),
                ko: getTravelText(item.name, "ko"),
                en: getTravelText(item.name, "en")
            },
            type: item.type || "游玩体验",
            time: item.time || "1–2小时",
            description: {
                zh: getTravelText(item.description, "zh"),
                ko: getTravelText(item.description, "ko"),
                en: getTravelText(item.description, "en")
            }
        });
    }
}


// 为已有地区添加餐厅推荐，不覆盖原有 foods
function addRestaurantsSafely(cityName, newRestaurants) {
    const city = travelData[cityName];

    if (!city) {
        console.warn("找不到地区，跳过餐厅补充：" + cityName);
        return;
    }

    if (!Array.isArray(city.restaurants)) {
        city.restaurants = [];
    }

    for (const item of newRestaurants) {
        const newNameZh = getTravelText(item.name, "zh").trim();

        if (!newNameZh) {
            console.warn("餐厅缺少中文名称，跳过：", item);
            continue;
        }

        const alreadyExists = city.restaurants.some(existing => {
            return getTravelText(existing.name, "zh").trim() === newNameZh;
        });

        if (alreadyExists) {
            console.log("餐厅已存在，跳过：" + cityName + " - " + newNameZh);
            continue;
        }

        city.restaurants.push({
            name: {
                zh: getTravelText(item.name, "zh"),
                ko: getTravelText(item.name, "ko"),
                en: getTravelText(item.name, "en")
            },
            area: {
                zh: getTravelText(item.area, "zh"),
                ko: getTravelText(item.area, "ko"),
                en: getTravelText(item.area, "en")
            },
            specialty: {
                zh: getTravelText(item.specialty, "zh"),
                ko: getTravelText(item.specialty, "ko"),
                en: getTravelText(item.specialty, "en")
            },
            description: {
                zh: getTravelText(item.description, "zh"),
                ko: getTravelText(item.description, "ko"),
                en: getTravelText(item.description, "en")
            },
            recommendedDishes: Array.isArray(item.recommendedDishes)
                ? item.recommendedDishes.slice(0, 3).map(dish => ({
                    name: {
                        zh: getTravelText(dish.name, "zh"),
                        ko: getTravelText(dish.name, "ko"),
                        en: getTravelText(dish.name, "en")
                    },
                    description: {
                        zh: getTravelText(dish.description, "zh"),
                        ko: getTravelText(dish.description, "ko"),
                        en: getTravelText(dish.description, "en")
                    }
                }))
                : []
        });
    }
}


// 检查所有地区的景点数量
function checkTravelDataAttractions() {
    console.table(
        Object.entries(travelData).map(([cityName, cityInfo]) => ({
            地区: cityName,
            景点数量: cityInfo.attractions?.length || 0,
            美食数量: cityInfo.foods?.length || 0,
            餐厅数量: cityInfo.restaurants?.length || 0
        }))
    );

    console.log("当前地区总数：", Object.keys(travelData).length);
}


