function addExpansionItemsOnce(cityName, items, field, getName) {
    const city = travelData[cityName];
    if (!city) {
        console.warn("未找到地区，跳过：", cityName);
        return;
    }

    if (!Array.isArray(city[field])) city[field] = [];

    const existing = new Set(
        city[field].map(item => getName(item)).filter(Boolean)
    );

    items.forEach(item => {
        const name = getName(item);
        if (name && !existing.has(name)) {
            city[field].push(item);
            existing.add(name);
        }
    });
}

for (const [cityName, info] of Object.entries(cityExpansionBatch20261108)) {
    addExpansionItemsOnce(
        cityName,
        info.attractions,
        "attractions",
        item => item?.name?.zh || item?.name || item?.[0]
    );

    addExpansionItemsOnce(
        cityName,
        info.foods,
        "foods",
        item => item?.name?.zh || item?.name || item?.[0]
    );

    addExpansionItemsOnce(
        cityName,
        info.restaurants,
        "restaurants",
        item => item?.name?.zh || item?.name || item?.[0]
    );
}

console.log("第一批地区数据扩充完成。");

