// 美食安全追加函数
function addFoodsSafely(cityName, newFoods) {
    const city = travelData[cityName];
    if (!city) return;

    if (!Array.isArray(city.foods)) city.foods = [];

    for (const item of newFoods) {
        const nameZh = item.name.zh.trim();

        if (city.foods.some(old =>
            getTravelText(old.name, "zh").trim() === nameZh
        )) continue;

        city.foods.push({
            name: {
                zh: item.name.zh,
                ko: item.name.ko,
                en: item.name.en
            },
            type: "美食",
            description: {
                zh: item.description.zh,
                ko: item.description.ko,
                en: item.description.en
            }
        });
    }
}

