function upgradeLegacyList(cityName, field, kind) {
    const city = travelData[cityName];
    if (!city || Array.isArray(city[field]) || !city[field] || typeof city[field] !== 'object') return;
    const old = city[field];
    city[field] = Object.entries(old).map(([zh, value]) => {
        const en = Array.isArray(value) ? value[0] : '';
        const oldDesc = Array.isArray(value) ? value[1] : '';
        if (kind === 'attractions') return {
            name: {zh, ko: legacyKoNames[cityName]?.[zh] || zh, en: en || zh}, type: '景点', time: '1–2小时',
            description: {zh: oldDesc ? `${zh}是当地具有代表性的游览地点，可结合现场展览、建筑或自然景观安排参观。` : `参观${zh}，了解当地历史文化或自然景观。`, ko: `${zh}은(는) 현지의 대표적인 관광 명소입니다. 전시와 건축 또는 자연 경관을 둘러보세요.`, en: oldDesc || `Visit ${en || zh} and explore its local history, culture or scenery.`}
        };
        return {
            name: {zh, ko: legacyKoNames[cityName]?.[zh] || zh, en: en || zh}, type: '美食',
            description: {zh: oldDesc ? `${zh}是当地常见特色风味，建议选择口碑稳定的店铺品尝。` : `品尝当地特色${zh}。`, ko: `${zh}은(는) 현지의 대표적인 음식입니다. 평판이 좋은 식당에서 맛보세요.`, en: oldDesc || `A local specialty worth trying at a reputable restaurant.`}
        };
    });
}
function addBatchAttractions(cityName, list) {
    const c = travelData[cityName]; if (!c) return;
    if (!Array.isArray(c.attractions)) c.attractions = [];
    const seen = new Set(c.attractions.map(x => batchText(x?.name, 'zh').trim()));
    for (const x of list) if (!seen.has(x.name.zh)) { c.attractions.push(x); seen.add(x.name.zh); }
}
function addBatchFoods(cityName, list) {
    const c = travelData[cityName]; if (!c) return;
    if (!Array.isArray(c.foods)) c.foods = [];
    const seen = new Set(c.foods.map(x => batchText(x?.name, 'zh').trim()));
    for (const x of list) if (!seen.has(x.name.zh)) { c.foods.push(x); seen.add(x.name.zh); }
}
function addBatchRestaurants(cityName, list) {
    const c = travelData[cityName]; if (!c) return;
    if (!Array.isArray(c.restaurants)) c.restaurants = [];
    const seen = new Set(c.restaurants.map(x => batchText(x?.name, 'zh').trim()));
    for (const x of list) if (!seen.has(x.name.zh)) { c.restaurants.push(x); seen.add(x.name.zh); }
}
