// ======================================================
// 2026-11-08 第一批：10个地区景点、美食扩充
// 青岛、三亚、丽江、哈尔滨、桂林、大邱、仁川、庆州、福冈、札幌
// 自动去重，不覆盖原有内容
// ======================================================

function addFirstBatchData(cityName, attractions, foods) {
    const city = travelData[cityName];
    if (!city) {
        console.warn("找不到地区：" + cityName);
        return;
    }

    if (!Array.isArray(city.attractions)) city.attractions = [];
    if (!Array.isArray(city.foods)) city.foods = [];

    const attractionNames = new Set(
        city.attractions.map(x => batchText(x.name, "zh").trim())
    );

    attractions.forEach(a => {
        if (attractionNames.has(a[0])) return;

        city.attractions.push({
            name: { zh: a[0], ko: a[1], en: a[2] },
            type: a[3],
            time: a[4],
            description: { zh: a[5], ko: a[6], en: a[7] }
        });

        attractionNames.add(a[0]);
    });

    const foodNames = new Set(
        city.foods.map(x => batchText(x.name, "zh").trim())
    );

    foods.forEach(f => {
        if (foodNames.has(f[0])) return;

        city.foods.push({
            name: { zh: f[0], ko: f[1], en: f[2] },
            type: "美食",
            description: { zh: f[3], ko: f[4], en: f[5] }
        });

        foodNames.add(f[0]);
    });
}

