// 按中文名称删除已经确认重复的景点
function removeDuplicateAttractions(cityName, namesToRemove) {
    const city = travelData[cityName];

    if (!city || !Array.isArray(city.attractions)) {
        console.warn("找不到地区或景点数据：" + cityName);
        return;
    }

    const before = city.attractions.length;

    city.attractions = city.attractions.filter(attraction => {
        const nameZh = getTravelText(attraction.name, "zh").trim();

        return !namesToRemove.includes(nameZh);
    });

    const removed = before - city.attractions.length;

    console.log(
        cityName + "：合并重复景点，删除 " + removed + " 条"
    );
}


