// =====================================================
// 全数据库景点质量检测 V2
// 标准：每个地区至少20个真实独立景点
// 在所有数据补充、删除、去重操作执行完成后运行
// 不自动删除、不自动编造景点
// =====================================================

(function runFinalAttractionAudit() {

    const MIN_ATTRACTIONS = 20;

    const report = {
        地区总数: 0,
        景点记录总数: 0,
        有效独立景点总数: 0,

        景点不足20个: [],
        名称完全重复: [],
        名称相似待核实: [],

        中文名称缺失: [],
        韩语名称缺失: [],
        英文名称缺失: [],

        中文介绍缺失: [],
        韩语介绍缺失: [],
        英文介绍缺失: [],

        数据结构异常: []
    };

    // 统一清理景点名称
    function cleanName(value) {
        return String(value || "")
            .normalize("NFKC")
            .replace(/[\s·・，,。！？、（）()\[\]【】「」『』\-—_]/g, "")
            .toLowerCase();
    }

    // 兼容字符串、中韩英对象和旧数组结构
    function readName(item, language) {

        if (!item) return "";

        if (Array.isArray(item)) {
            const index = {
                zh: 0,
                ko: 1,
                en: 2
            }[language];

            return String(item[index] || "").trim();
        }

        const value = item.name;

        if (typeof value === "string") {
            return language === "zh" ? value.trim() : "";
        }

        if (value && typeof value === "object") {
            const keys = {
                zh: ["zh", "cn", "zh-CN"],
                ko: ["ko", "kr"],
                en: ["en"]
            };

            for (const key of keys[language]) {
                if (value[key]) {
                    return String(value[key]).trim();
                }
            }
        }

        return "";
    }

    // 兼容 description 和旧数组介绍
    function readDescription(item, language) {

        if (!item) return "";

        if (Array.isArray(item)) {
            const index = {
                zh: 5,
                ko: 6,
                en: 7
            }[language];

            return String(item[index] || "").trim();
        }

        const value = item.description || item.desc;

        if (typeof value === "string") {
            return language === "zh" ? value.trim() : "";
        }

        if (value && typeof value === "object") {
            const keys = {
                zh: ["zh", "cn", "zh-CN"],
                ko: ["ko", "kr"],
                en: ["en"]
            };

            for (const key of keys[language]) {
                if (value[key]) {
                    return String(value[key]).trim();
                }
            }
        }

        return "";
    }

    // 检查数据库是否存在
    if (
        typeof travelData === "undefined" ||
        !travelData ||
        typeof travelData !== "object"
    ) {
        console.error("景点检测失败：travelData 不存在。");
        return;
    }

    // 遍历全部地区
    for (const [cityName, cityData] of Object.entries(travelData)) {

        report.地区总数++;

        if (
            !cityData ||
            !Array.isArray(cityData.attractions)
        ) {
            report.数据结构异常.push({
                地区: cityName,
                问题: "景点数组不存在"
            });

            report.景点不足20个.push({
                地区: cityName,
                数量: 0,
                还缺: 20
            });

            continue;
        }

        const attractions = cityData.attractions;

        report.景点记录总数 += attractions.length;

        const seen = new Map();
        const validAttractions = [];

        // 检查每个景点
        attractions.forEach((item, index) => {

            if (
                !item ||
                typeof item !== "object"
            ) {
                report.数据结构异常.push({
                    地区: cityName,
                    序号: index + 1,
                    问题: "景点记录不是有效对象"
                });

                return;
            }

            const zhName = readName(item, "zh");
            const koName = readName(item, "ko");
            const enName = readName(item, "en");

            const zhDesc = readDescription(item, "zh");
            const koDesc = readDescription(item, "ko");
            const enDesc = readDescription(item, "en");

            const location = {
                地区: cityName,
                景点: zhName || "未命名",
                序号: index + 1
            };

            if (!zhName) {
                report.中文名称缺失.push(location);
            }

            if (!koName) {
                report.韩语名称缺失.push(location);
            }

            if (!enName) {
                report.英文名称缺失.push(location);
            }

            if (!zhDesc) {
                report.中文介绍缺失.push(location);
            }

            if (!koDesc) {
                report.韩语介绍缺失.push(location);
            }

            if (!enDesc) {
                report.英文介绍缺失.push(location);
            }

            const normalized = cleanName(zhName);

            if (!normalized) {
                return;
            }

            // 完全重复名称检查
            if (seen.has(normalized)) {

                report.名称完全重复.push({
                    地区: cityName,
                    景点1: seen.get(normalized),
                    景点2: zhName
                });

                return;
            }

            seen.set(normalized, zhName);

            validAttractions.push({
                name: zhName,
                normalized: normalized
            });

        });

        report.有效独立景点总数 += validAttractions.length;

        // 检查独立景点数量
        if (validAttractions.length < MIN_ATTRACTIONS) {

            report.景点不足20个.push({
                地区: cityName,
                数量: validAttractions.length,
                还缺: MIN_ATTRACTIONS - validAttractions.length
            });

        }

        // 名称包含关系只作为人工核实候选
        // 不会自动认定为重复，也不会自动删除
        for (
            let i = 0;
            i < validAttractions.length;
            i++
        ) {

            for (
                let j = i + 1;
                j < validAttractions.length;
                j++
            ) {

                const a = validAttractions[i];
                const b = validAttractions[j];

                if (
                    a.normalized.length >= 3 &&
                    b.normalized.length >= 3 &&
                    (
                        a.normalized.includes(b.normalized) ||
                        b.normalized.includes(a.normalized)
                    )
                ) {

                    report.名称相似待核实.push({
                        地区: cityName,
                        景点1: a.name,
                        景点2: b.name
                    });

                }
            }
        }
    }

    // 输出完整检测报告
    console.log("========== 全数据库最终检测 ==========");

    console.log("地区总数：", report.地区总数);

    console.log("景点记录总数：", report.景点记录总数);

    console.log("有效独立景点总数：", report.有效独立景点总数);

    console.log("每地区最低标准：", MIN_ATTRACTIONS);

    console.log("--------------------------------------");

    for (const [category, items] of Object.entries(report)) {

        if (Array.isArray(items)) {

            console.log(
                category + "：",
                items.length
            );

            if (items.length > 0) {
                console.table(items);
            }

        }
    }

    // 统计总缺口
    const totalMissing = report.景点不足20个.reduce(
        (sum, item) => sum + item.还缺,
        0
    );

    console.log("--------------------------------------");

    console.log(
        "未达到20个景点的地区：",
        report.景点不足20个.length
    );

    console.log(
        "全部地区还需要补充的景点记录：",
        totalMissing
    );

    console.log("========== 检测完成 ==========");

    // 保存检测结果，方便后续批量补充
    window.fullAttractionAuditReport = report;

})();
// =====================================================
// 全地区景点储备检查器 V3
// 标准：每个地区至少20个独立景点
// 不删除、不修改、不生成虚假景点
// =====================================================

(function auditAllDestinationAttractions() {

    const MIN_ATTRACTIONS = 20;

    const report = {
        totalCities: 0,
        totalAttractions: 0,
        qualifiedCities: [],
        insufficientCities: [],
        invalidCities: [],
        totalMissing: 0
    };

    function getChineseName(item) {
        if (!item) return "";

        if (typeof item === "string") return item.trim();

        if (Array.isArray(item)) {
            return String(item[0] || "").trim();
        }

        if (item.name && typeof item.name === "object") {
            return String(item.name.zh || item.name.cn || "").trim();
        }

        if (typeof item.name === "string") {
            return item.name.trim();
        }

        return "";
    }

    function normalizeName(name) {
        return String(name || "")
            .normalize("NFKC")
            .replace(/[\s·・，,。！？、（）()\[\]【】「」『』\-—_]/g, "")
            .toLowerCase();
    }

    if (
        typeof travelData === "undefined" ||
        !travelData ||
        typeof travelData !== "object"
    ) {
        console.error("未找到 travelData，检查失败。");
        return;
    }

    for (const [city, data] of Object.entries(travelData)) {

        report.totalCities++;

        if (!data || !Array.isArray(data.attractions)) {
            report.invalidCities.push({
                地区: city,
                问题: "attractions 不是有效数组"
            });
            continue;
        }

        const seen = new Set();
        const uniqueAttractions = [];

        for (const item of data.attractions) {

            const name = getChineseName(item);
            const normalized = normalizeName(name);

            if (!normalized || seen.has(normalized)) {
                continue;
            }

            seen.add(normalized);
            uniqueAttractions.push(name);
        }

        const count = uniqueAttractions.length;

        report.totalAttractions += count;

        if (count >= MIN_ATTRACTIONS) {

            report.qualifiedCities.push({
                地区: city,
                景点数量: count
            });

        } else {

            const missing = MIN_ATTRACTIONS - count;

            report.insufficientCities.push({
                地区: city,
                当前数量: count,
                还需补充: missing,
                当前景点: uniqueAttractions
            });

            report.totalMissing += missing;
        }
    }

    console.log("========== 全地区景点储备检查 ==========");

    console.log("地区总数：", report.totalCities);
    console.log("景点总数：", report.totalAttractions);
    console.log("已达到20个的地区：", report.qualifiedCities.length);
    console.log("未达到20个的地区：", report.insufficientCities.length);
    console.log("景点数量缺口：", report.totalMissing);

    console.log("========== 未达标地区 ==========");
    console.table(
        report.insufficientCities.map(item => ({
            地区: item.地区,
            当前数量: item.当前数量,
            还需补充: item.还需补充
        }))
    );

    console.log("========== 数据结构异常 ==========");
    console.table(report.invalidCities);

    window.destinationAttractionAudit = report;

    console.log("完整检查结果已保存：window.destinationAttractionAudit");

})();
