// 执行第二段追加
(function addAttractionBatch30Part2() {
    const report = [];
    const normalize = value => String(value || "")
        .normalize("NFKC")
        .replace(/[\\s·・，,。！？、（）()\\[\\]【】「」『』\\-—_]/g, "")
        .toLowerCase();

    for (const [city, items] of Object.entries(attractionBatch30Part2)) {
        const data = travelData[city];

        if (!data || !Array.isArray(data.attractions)) {
            report.push({地区: city, 状态: "未找到地区或景点数组"});
            continue;
        }

        const existing = new Set(
            data.attractions.map(item => normalize(item?.name?.zh || item?.name))
        );

        let added = 0;
        let skipped = 0;

        for (const item of items) {
            const name = normalize(item?.name?.zh);
            if (!name || existing.has(name)) {
                skipped++;
                continue;
            }
            data.attractions.push(item);
            existing.add(name);
            added++;
        }

        report.push({
            地区: city,
            本次新增: added,
            重复跳过: skipped,
            当前景点数: data.attractions.length,
            达到20个: data.attractions.length >= 20
        });
    }

    console.table(report);
    console.log("第一批30地区景点补充（第2段）执行完成。");
})();
