// 执行第2段：按中文名称去重
(function () {
    const normalize = value => String(value || "")
        .normalize("NFKC")
        .replace(/[\\s·・，,。！？、（）()\\[\\]【】「」『』\\-—_]/g, "")
        .toLowerCase();

    const report = [];

    for (const [city, items] of Object.entries(attractionExpansionPart2)) {
        const data = travelData[city];

        if (!data || !Array.isArray(data.attractions)) {
            report.push({地区: city, 状态: "未找到地区数据"});
            continue;
        }

        const existing = new Set(
            data.attractions.map(item => normalize(item?.name?.zh || item?.name))
        );

        let added = 0;
        let skipped = 0;

        for (const item of items) {
            const key = normalize(item?.name?.zh);

            if (!key || existing.has(key)) {
                skipped++;
                continue;
            }

            data.attractions.push(item);
            existing.add(key);
            added++;
        }

        report.push({
            地区: city,
            本次新增: added,
            重复跳过: skipped,
            当前条数: data.attractions.length
        });
    }

    console.table(report);
    console.log("景点扩充合并批次第2段执行完成。");
})();
