// 下一批30地区：数据核对
// ==========================================
(() => {
    const batch30 = [
        "南京", "首尔", "上海", "北京", "武汉", "釜山",
        "永州", "闻庆", "金海", "巨济", "泗川", "河东",
        "潭阳", "宝城", "光阳", "益山", "扶安", "茂朱",
        "平昌", "麟蹄", "横城", "三陟", "东海", "太白",
        "神户", "广岛", "金泽", "大田", "丽水", "浦项"
    ];

    const getName = item =>
        String(item?.name?.zh || item?.name || item?.[0] || "").trim();

    const report = batch30.map(name => {
        const city = travelData[name];

        if (!city) {
            return {
                地区: name,
                景点数: 0,
                美食数: 0,
                餐厅数: 0,
                状态: "数据库没有该地区"
            };
        }

        const uniqueAttractions = new Set(
            (city.attractions || []).map(getName).filter(Boolean)
        );

        const uniqueFoods = new Set(
            (city.foods || []).map(getName).filter(Boolean)
        );

        const uniqueRestaurants = new Set(
            (city.restaurants || []).map(getName).filter(Boolean)
        );

        const attractions = uniqueAttractions.size;
        const foods = uniqueFoods.size;
        const restaurants = uniqueRestaurants.size;

        return {
            地区: name,
            景点数: attractions,
            美食数: foods,
            餐厅数: restaurants,
            景点达标: attractions >= 20 ? "是" : "否",
            餐厅达标: restaurants >= 10 ? "是" : "否",
            状态: attractions >= 20 && restaurants >= 10
                ? "完成"
                : "待补充"
        };
    });

    console.table(report);

    window.nextBatch30Audit = report;

    console.log("本批地区总数：", report.length);
    console.log(
        "实际完成地区：",
        report.filter(x => x.状态 === "完成").length
    );
    console.log(
        "待补充地区：",
        report.filter(x => x.状态 !== "完成").length
    );
})();
